using BankSystem.Notification.Application.DTOs;using BankSystem.Notification.Application.Interfaces;using BankSystem.Notification.Application.Queries;using MediatR;namespace BankSystem.Notification.Application.Handlers;public sealed class GetNotificationHandler(INotificationRepository r):IRequestHandler<GetNotificationQuery,NotificationDto?>{public async Task<NotificationDto?>Handle(GetNotificationQuery q,CancellationToken ct){var n=await r.GetAsync(q.Id,ct);return n is null?null:new(n.Id,n.UserId,n.Type.ToString(),n.Status.ToString(),n.Subject,n.Body,n.CreatedAt,n.SentAt,n.Error);}}
